import{_ as t,o as d,c as o,a0 as a}from"./chunks/framework.DoRPXVp_.js";const h=JSON.parse('{"title":"Build & Release Reference","description":"","frontmatter":{},"headers":[],"relativePath":"build-reference.md","filePath":"build-reference.md"}'),c={name:"build-reference.md"};function r(i,e,l,n,s,m){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="build-release-reference" tabindex="-1">Build &amp; Release Reference <a class="header-anchor" href="#build-release-reference" aria-label="Permalink to &quot;Build &amp; Release Reference&quot;">​</a></h1><h2 id="makefile-commands" tabindex="-1">Makefile Commands <a class="header-anchor" href="#makefile-commands" aria-label="Permalink to &quot;Makefile Commands&quot;">​</a></h2><h3 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>SERVICE</code></td><td>(required)</td><td>Target service: <code>manager</code>, <code>lattice</code> (agent), <code>latticed</code> (all-in-one), <code>lrp</code> (relay)</td></tr><tr><td><code>EDITION</code></td><td><code>community</code></td><td>Build edition: <code>community</code> (no build tags) or <code>pro</code> (adds <code>-tags pro</code>)</td></tr><tr><td><code>TAG</code></td><td><code>dev</code></td><td>Docker image tag</td></tr><tr><td><code>VERSION</code></td><td><code>dev</code></td><td>Version string injected via ldflags</td></tr><tr><td><code>REGISTRY</code></td><td><code>ghcr.io/alatticeio</code></td><td>Container registry</td></tr><tr><td><code>TARGETOS</code></td><td><code>linux</code></td><td>Target OS for Go build</td></tr><tr><td><code>TARGETARCH</code></td><td><code>amd64</code></td><td>Target arch for Go build</td></tr><tr><td><code>ENV</code></td><td><code>dev</code></td><td>Deployment environment (for kustomize overlays)</td></tr><tr><td><code>BUILD_CACHE_ARGS</code></td><td>(empty)</td><td>Docker BuildKit cache flags (set <code>--cache-from type=gha --cache-to type=gha,mode=max</code> in CI)</td></tr></tbody></table><h3 id="build-commands" tabindex="-1">Build Commands <a class="header-anchor" href="#build-commands" aria-label="Permalink to &quot;Build Commands&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>make build</code></td><td>Build a single service binary. For <code>manager</code>/<code>latticed</code>, builds UI first. Outputs to <code>bin/&lt;SERVICE&gt;</code>.</td><td><code>make build SERVICE=latticed</code> — community binary<br><code>make build SERVICE=latticed EDITION=pro</code> — Pro binary</td></tr><tr><td><code>make build-all</code></td><td>Build all services (<code>manager</code>, <code>lattice</code>, <code>latticed</code>, <code>lrp</code>) as community binaries.</td><td><code>make build-all</code></td></tr><tr><td><code>make build-ui</code></td><td>Build the Vue 3 frontend. Runs <code>pnpm install &amp;&amp; pnpm build</code> in <code>fronted/</code>, outputs to <code>internal/web/dist/</code>.</td><td><code>make build-ui</code></td></tr><tr><td><code>make ebpf-gen</code></td><td>Generate eBPF Go bindings from <code>tc_ingress.bpf.c</code>. On macOS, uses Homebrew LLVM at <code>/opt/homebrew/opt/llvm/bin/clang</code>.</td><td><code>make ebpf-gen</code></td></tr></tbody></table><h3 id="test-commands" tabindex="-1">Test Commands <a class="header-anchor" href="#test-commands" aria-label="Permalink to &quot;Test Commands&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>make test</code></td><td>Run all unit tests (except e2e) with envtest. Requires <code>setup-envtest</code> which downloads K8s API binaries for test mocking.</td><td><code>make test</code></td></tr><tr><td><code>make test-latticed</code></td><td>Run latticed-specific tests: <code>cmd/latticed</code>, <code>internal/nats</code>, <code>internal/db</code>.</td><td><code>make test-latticed</code></td></tr><tr><td><code>make e2e-setup</code></td><td>One-click E2E environment setup: creates k3d cluster, builds Docker images for <code>manager</code> + <code>lattice</code>, imports into k3d, deploys via kustomize.</td><td><code>make e2e-setup</code></td></tr><tr><td><code>make test-e2e</code></td><td>Run E2E tests with port-forwarding. Requires a running k3d cluster with Lattice deployed.</td><td><code>make test-e2e</code></td></tr><tr><td><code>make e2e</code></td><td>Combined: <code>e2e-setup</code> + <code>test-e2e</code>. Cluster persists after tests for inspection.</td><td><code>make e2e</code></td></tr><tr><td><code>make e2e-teardown</code></td><td>Destroy the E2E k3d cluster and remove its kubeconfig.</td><td><code>make e2e-teardown</code></td></tr></tbody></table><h3 id="docker-commands" tabindex="-1">Docker Commands <a class="header-anchor" href="#docker-commands" aria-label="Permalink to &quot;Docker Commands&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>make docker-build</code></td><td>Build a single Docker image. For <code>manager</code>/<code>latticed</code>, builds UI first.</td><td><code>make docker-build SERVICE=lattice</code><br><code>make docker-build SERVICE=latticed EDITION=pro</code></td></tr><tr><td><code>make docker-build-all</code></td><td>Build Docker images for all 4 services.</td><td><code>make docker-build-all</code></td></tr><tr><td><code>make docker-push</code></td><td>Push a single Docker image to <code>REGISTRY</code>.</td><td><code>make docker-push SERVICE=latticed TAG=v0.1.0</code></td></tr><tr><td><code>make docker-push-all</code></td><td>Push all service images.</td><td><code>make docker-push-all</code></td></tr><tr><td><code>make docker-all</code></td><td>Build + push all images.</td><td><code>make docker-all</code></td></tr><tr><td><code>make docker</code></td><td>Build + push single image.</td><td><code>make docker SERVICE=latticed</code></td></tr><tr><td><code>make docker-buildx</code></td><td>Multi-arch build with <code>docker buildx</code> for cross-platform support (linux/arm64, amd64, s390x, ppc64le).</td><td><code>make docker-buildx IMG=ghcr.io/alatticeio/manager:v0.1.0</code></td></tr><tr><td><code>make docker-installer</code></td><td>Build installer image locally (single platform).</td><td><code>make docker-installer</code></td></tr><tr><td><code>make docker-installer-push</code></td><td>Build + push multi-arch installer image via buildx (linux/amd64, arm64).</td><td><code>make docker-installer-push</code></td></tr></tbody></table><h3 id="k8s-crd-commands" tabindex="-1">K8s / CRD Commands <a class="header-anchor" href="#k8s-crd-commands" aria-label="Permalink to &quot;K8s / CRD Commands&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>make manifests</code></td><td>Generate CRD YAML, ClusterRole, and WebhookConfiguration via controller-gen. Output to <code>config/crd/bases/</code>.</td></tr><tr><td><code>make generate</code></td><td>Generate DeepCopy methods for CRD types + compile protobuf definitions.</td></tr><tr><td><code>make install</code></td><td>Install CRDs into a K8s cluster.</td></tr><tr><td><code>make uninstall</code></td><td>Remove CRDs from a K8s cluster.</td></tr><tr><td><code>make deploy</code></td><td>Deploy according to <code>ENV</code> (uses kustomize overlay at <code>config/lattice/overlays/&lt;ENV&gt;/</code>).</td></tr><tr><td><code>make undeploy</code></td><td>Remove the deployment.</td></tr><tr><td><code>make deploy-aio</code></td><td>Deploy all-in-one mode (latticed) to K8s. Creates namespace, installs CRDs, applies kustomize manifests with image substitution.</td></tr><tr><td><code>make undeploy-aio</code></td><td>Remove all-in-one deployment.</td></tr><tr><td><code>make build-installer</code></td><td>Build kustomize output manifests into <code>deploy/quickstart/</code> for installer to fetch.</td></tr><tr><td><code>make yaml</code></td><td>Build all-in-one kustomize output to <code>config/lattice.yaml</code>.</td></tr></tbody></table><h3 id="code-quality-commands" tabindex="-1">Code Quality Commands <a class="header-anchor" href="#code-quality-commands" aria-label="Permalink to &quot;Code Quality Commands&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>make lint</code></td><td>Run golangci-lint.</td></tr><tr><td><code>make lint-fix</code></td><td>Run golangci-lint with <code>--fix</code> for auto-fixable issues.</td></tr><tr><td><code>make lint-config</code></td><td>Verify golangci-lint configuration.</td></tr><tr><td><code>make fmt</code></td><td>Run <code>go fmt ./...</code>.</td></tr><tr><td><code>make vet</code></td><td>Run <code>go vet ./...</code>.</td></tr></tbody></table><h3 id="tool-installation-commands" tabindex="-1">Tool Installation Commands <a class="header-anchor" href="#tool-installation-commands" aria-label="Permalink to &quot;Tool Installation Commands&quot;">​</a></h3><p>These auto-download the required tools to <code>./bin/</code> if not already present:</p><table tabindex="0"><thead><tr><th>Command</th><th>Tool</th><th>Version Source</th></tr></thead><tbody><tr><td><code>make kustomize</code></td><td>kustomize v5.6.0</td><td>Hardcoded</td></tr><tr><td><code>make controller-gen</code></td><td>controller-tools v0.18.0</td><td>Hardcoded</td></tr><tr><td><code>make setup-envtest</code></td><td>setup-envtest (matching controller-runtime)</td><td>From go.mod</td></tr><tr><td><code>make golangci-lint</code></td><td>golangci-lint v1.64.5</td><td>Hardcoded</td></tr></tbody></table><h3 id="build-details" tabindex="-1">Build Details <a class="header-anchor" href="#build-details" aria-label="Permalink to &quot;Build Details&quot;">​</a></h3><p><strong>Version injection</strong> — The following values are injected via Go ldflags:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-x &#39;lattice/pkg/version.Version=&lt;git-describe&gt;&#39;</span></span>
<span class="line"><span>-x &#39;lattice/pkg/version.GitCommit=&lt;git-rev-parse&gt;&#39;</span></span>
<span class="line"><span>-x &#39;lattice/pkg/version.BuildTime=&lt;UTC timestamp&gt;&#39;</span></span>
<span class="line"><span>-x &#39;lattice/pkg/version.GoVersion=&lt;go version&gt;&#39;</span></span></code></pre></div><p><strong>UI build</strong> — <code>manager</code> and <code>latticed</code> services embed the Vue 3 frontend via <code>//go:embed internal/web/dist/</code>. The <code>build-ui</code> target must run before building these services. Both <code>make build</code> and <code>make docker-build</code> handle this automatically.</p><p><strong>Community vs Pro</strong> — The <code>EDITION</code> variable controls Go build tags:</p><ul><li><code>community</code> (default): no build tags — community stubs compile in, Pro code is excluded</li><li><code>pro</code>: adds <code>-tags pro</code> — Pro implementations compile in, community stubs are excluded</li></ul><p>Pro features include: TURN server, Dex OIDC/SSO, telemetry/VictoriaMetrics push, eBPF policy enforcement, dashboard analytics, network monitoring, Ed25519 JWT license verification.</p>`,24)])])}const p=t(c,[["render",r]]);export{h as __pageData,p as default};
